package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;

import java.math.BigInteger;
import java.util.List;

import org.eclipse.rdf4j.model.util.Values;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class MemoryStoreLocalBindInputRegressionTest {

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void localBindIsEvaluatedAgainstItsOwnTargetBeforeFilter() throws Exception {
		assertInitialBindingDoesNotReplaceLocalBind(
				"SELECT ?x WHERE { BIND(1 AS ?x) FILTER(?x = 1) }", "x");
	}

	@Test
	void projectionAliasReadsTheLocalBindValue() throws Exception {
		assertInitialBindingDoesNotReplaceLocalBind(
				"SELECT ?alias WHERE { BIND(1 AS ?x) BIND(?x AS ?alias) FILTER(?alias = 1) }", "alias");
	}

	@Test
	void nestedProjectionAliasReadsTheSubqueryLocalBindValue() throws Exception {
		assertInitialBindingDoesNotReplaceLocalBind(
				"SELECT ?alias WHERE { { SELECT (?x AS ?alias) WHERE { BIND(1 AS ?x) } } FILTER(?alias = 1) }",
				"alias");
	}

	@Test
	void failedLocalBindLeavesAnInitiallyBoundTargetActuallyUnbound() throws Exception {
		List<BindingSet> rows = evaluateWithInitialBinding(
				"SELECT ?x ?copy (BOUND(?x) AS ?bound) WHERE { BIND(?missing AS ?x) BIND(?x AS ?copy) }", "x");

		assertThat(rows).hasSize(1);
		BindingSet row = rows.get(0);
		assertThat(row.hasBinding("x")).isFalse();
		assertThat(row.getBinding("x")).isNull();
		assertThat(row.getValue("x")).isNull();
		assertThat(row.hasBinding("copy")).isFalse();
		assertThat(row.getBinding("copy")).isNull();
		assertThat(row.getBindingNames()).doesNotContain("x", "copy");
		assertThat(row.getValue("bound")).isEqualTo(Values.literal(false));
		assertThat(row.size()).isEqualTo(1);
	}

	private void assertInitialBindingDoesNotReplaceLocalBind(String sparql, String projectedVariable)
			throws Exception {
		List<BindingSet> rows = evaluateWithInitialBinding(sparql, "x");
		assertThat(rows).singleElement()
				.satisfies(row -> assertThat(row.getValue(projectedVariable))
						.isEqualTo(Values.literal(BigInteger.ONE)));
	}

	private List<BindingSet> evaluateWithInitialBinding(String sparql, String variable) throws Exception {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			TupleQuery query = connection.prepareTupleQuery(QueryLanguage.SPARQL, sparql);
			query.setBinding(variable, Values.literal(2));
			try (TupleQueryResult result = query.evaluate()) {
				return QueryResults.asList(result);
			}
		}
	}
}
